command:
const effectName = args[1];
if (! effectName) {
  return;
}

// Récupère le compteur stocké dans les flags du token
let flagData = token.document.getFlag("world", effectName) || { count: 0 };
let count = flagData.count;
if (args[0] === "on") {
  count++;
  await token.document.setFlag("world", effectName, { count: count });

  // Si c'est le premier effet, on lance l'animation
  if (count === 1) {
    new Sequence()
      .effect()
      .file(effectName) // <- change ton animation
      .attachTo(token)
      .persist()
      .name(effectName)
      .scaleToObject(1.3)
      .play();
  }

} else if (args[0] === "off") {
  count = Math.max(count - 1, 0);
  await token.document.setFlag("world", effectName, count);

  // Si plus aucun effet actif, on arrête l'animation
  if (count === 0) {
    Sequencer.EffectManager.endEffects({ name: effectName, object: token });
  }
}
